"""Renders physics_params.yaml — the anti-black-box artifact for the physics layer.

Every leaf is a (value, origin) pair and every rendered value line carries the
origin as a comment: sourced, fitted (naming its notebook) or stylised. The
emitter is hand-rolled so output is byte-deterministic — keys sorted at every
level, shortest-repr floats — and `git diff` after a make fit rerun is empty.
"""

import json
import math


class IncompleteParamsError(ValueError):
    pass


HEADER = (
    "# SENNA — fitted physics constants (F02). Generated by senna.physics.fits.run;\n"
    "# edit the fitters or configs/fits.yaml, never this file by hand.\n"
)


def render_params(params: dict, generated_at: str, *, header: str = HEADER) -> str:
    lines = [header]
    lines.append(
        f'generated_at: "{generated_at}"  # stylised — data watermark, not a clock:'
        " a rerun on the same ingest renders byte-identically"
    )
    lines.extend(_render_mapping(params, indent=0))
    return "\n".join(lines) + "\n"


ORIGIN_TAGS = ("sourced", "fitted", "stylised", "operational")


def validate_complete(params: dict) -> None:
    """Refuse a tree that cannot be read as physics. A null is an unfitted constant; a NaN
    or an infinity is a fit that failed and did not say so — `is None` never caught those,
    so they would have rendered into the yaml as `nan` and been loaded back as a float."""
    unusable = sorted(_unusable_paths(params, prefix=""))
    if unusable:
        raise IncompleteParamsError(
            "physics_params has null or non-finite constants — fit or verify before F05 "
            "reads them: " + ", ".join(unusable)
        )


def validate_origins(params: dict) -> None:
    """Every leaf must say where it came from. The tag is what makes the file an
    anti-black-box artifact rather than a list of numbers, so an untagged constant is a
    defect even when its value is right."""
    untagged = sorted(_untagged_paths(params, prefix=""))
    if untagged:
        raise IncompleteParamsError(
            "physics_params has constants with no provenance tag — every value needs one of "
            f"{', '.join(ORIGIN_TAGS)}: " + ", ".join(untagged)
        )


def _render_mapping(mapping: dict, indent: int) -> list[str]:
    pad = "  " * indent
    lines = []
    for key in sorted(mapping, key=str):
        node = mapping[key]
        if isinstance(node, dict):
            lines.append(f"{pad}{key}:")
            lines.extend(_render_mapping(node, indent + 1))
        else:
            value, origin = node
            lines.append(f"{pad}{key}: {_scalar(value)}  # {origin}")
    return lines


def _scalar(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, float):
        text = repr(value)  # shortest round-trip repr; safe_load returns the same float
        if "e" in text and "." not in text:
            # YAML 1.1 only reads scientific notation with a dot: "7e-06"
            # loads as a string, "7.0e-06" as the float
            text = text.replace("e", ".0e")
        return text
    if isinstance(value, str):
        return json.dumps(value)  # double-quoted, valid YAML, never reparsed as a date
    if isinstance(value, list):
        return "[" + ", ".join(_scalar(item) for item in value) + "]"
    return str(value)


def _unusable_paths(mapping: dict, prefix: str) -> list[str]:
    paths = []
    for key, node in mapping.items():
        dotted = f"{prefix}{key}"
        if isinstance(node, dict):
            paths.extend(_unusable_paths(node, f"{dotted}."))
        elif node[0] is None or (isinstance(node[0], float) and not math.isfinite(node[0])):
            paths.append(dotted)
    return paths


def _untagged_paths(mapping: dict, prefix: str) -> list[str]:
    paths = []
    for key, node in mapping.items():
        dotted = f"{prefix}{key}"
        if isinstance(node, dict):
            paths.extend(_untagged_paths(node, f"{dotted}."))
        else:
            origin = str(node[1]).strip() if len(node) > 1 else ""
            if not origin.startswith(ORIGIN_TAGS):
                paths.append(dotted)
    return paths
